from itertools import combinations

def balanced_sequences(n):
    # Generate all balanced sequences
    sequences = [''.join(seq) for seq in combinations('01' * n, n)]
    return sequences

def neighbors(sequences, n):
    # Find neighbors for each sequence
    neighbors_dict = {}
    for seq in sequences:
        for i in range(n):
            new_seq = seq[:i] + '*' + seq[i+1:]
            neighbors_dict[seq] = [seq[:i] + '0' + seq[i+1:] if new_seq == seq[:i] + '*' + seq[i+1:] else seq[:i] + '1' + seq[i+1:] for j in range(n) if new_seq == seq[:j] + '*' + seq[j+1:]]
    return neighbors_dict

def find_set(n):
    sequences = balanced_sequences(n)
    neighbors_dict = neighbors(sequences, n)
    S = set()
    for seq in sequences:
        if seq not in S:
            S.add(seq)
            for neighbor in neighbors_dict[seq]:
                if neighbor not in S:
                    S.add(neighbor)
    return list(S)

n = 5
S = find_set(n)
print(S)
